function filteredVouchers(){const q=$('#voucherSearch').value.trim().toLowerCase(),type=$('#voucherType').value,partner=$('#voucherPartner')?.value||'',from=$('#voucherFrom').value,to=$('#voucherTo').value;return state.vouchers.filter(v=>(!q||(v.number+' '+(v.partnerName||'')+' '+(v.description||'')).toLowerCase().includes(q))&&(!type||v.type===type)&&(!partner||v.partnerId===partner)&&(!from||v.date>=from)&&(!to||v.date<=to)).sort((a,b)=>(b.date+b.number).localeCompare(a.date+a.number))}
