function startVoucher(id=''){if(!canWrite())return;dirtyVoucher=false;const v=id?voucherById(id):null;$('#editVoucherId').value=v?.id||'';$('#formVoucherType').value=v?.type||'OUT';$('#formVoucherDate').value=v?.date||today();$('#formVoucherNumber').value=v?.number||'';$('#formInvoiceNo').value=v?.invoiceNo||'';$('#formPartner').value=v?.partnerId||'';$('#formAddress').value=v?.address||'';$('#formDescription').value=v?.description||'';$('#formWarehouse').value=v?.warehouse||state.settings?.defaultWarehouse||'Kho công ty';$('#formDeliverer').value=v?.delivererReceiver||'';$('#formStorekeeper').value=v?.storekeeper||'';$('#formApprover').value=v?.approver||'';$('#formVoucherNote').value=v?.note||'';voucherDraft=v?linesByVoucher(v.id).map(t=>{const i=itemById(t.itemId);return{key:crypto.randomUUID(),category:i?.category||'',itemType:i?.itemType||'',itemId:t.itemId,quantity:n(t.quantityIn)||n(t.quantityOut),condition:t.condition||'Mới',note:t.note||''}}):[{key:crypto.randomUUID(),category:'',itemType:'',itemId:'',quantity:'',condition:'Mới',note:''}];$('#voucherFormTitle').textContent=v?'Sửa phiếu '+v.number:'Lập phiếu nhập/xuất';updateVoucherBadge();renderVoucherLines();showPage('voucher-edit')}
function updateVoucherBadge(){const type=$('#formVoucherType').value,b=$('#voucherModeBadge');b.className='badge '+type.toLowerCase();b.textContent=type==='IN'?'PHIẾU NHẬP':'PHIẾU XUẤT'}
function syncVoucherDraft(){$$('#voucherLinesBody tr[data-key]').forEach(tr=>{const l=voucherDraft.find(x=>x.key===tr.dataset.key);if(!l)return;l.category=tr.querySelector('.line-category')?.value||'';l.itemType=tr.querySelector('.line-type')?.value||'';l.itemId=tr.querySelector('.line-item')?.value||'';l.quantity=tr.querySelector('.line-qty').value;l.condition=tr.querySelector('.line-condition').value;l.note=tr.querySelector('.line-note').value})}
function renderVoucherLines(){const stock=buildStock(),groups=groupValues();$('#voucherLinesBody').innerHTML=voucherDraft.map((l,k)=>{const selected=itemById(l.itemId);if(selected){l.category=selected.category;l.itemType=selected.itemType||''}const types=typeValues(l.category),items=state.items.filter(i=>(!l.category||i.category===l.category)&&(!l.itemType||i.itemType===l.itemType)).sort((a,b)=>a.code.localeCompare(b.code,'vi')||a.name.localeCompare(b.name,'vi')),st=selected?stock.get(selected.id).closing:'';return `<tr data-key="${h(l.key)}"><td>${k+1}</td><td><select class="line-category">${selectOptions(groups,'Chọn nhóm',l.category)}</select></td><td><select class="line-type">${selectOptions(types,'Chọn loại',l.itemType)}</select></td><td><select class="line-item item-select"><option value="">Chọn vật tư</option>${items.map(i=>`<option value="${h(i.id)}"${i.id===l.itemId?' selected':''}>${h(i.code)} — ${h(i.name)}</option>`).join('')}</select></td><td class="image-cell line-image">${selected?imageThumb(selected,'voucher-thumb'):'<span class="image-placeholder voucher-thumb">—</span>'}</td><td class="line-unit">${h(selected?.unit||'')}</td><td class="num line-stock ${n(st)<0?'stock-negative':''}">${selected?fmt(st):''}</td><td><input class="line-qty" type="number" min="0" step="any" value="${h(l.quantity)}"></td><td><select class="line-condition"><option${l.condition==='Mới'?' selected':''}>Mới</option><option${l.condition==='Cũ'?' selected':''}>Cũ</option><option${l.condition==='Hỏng'?' selected':''}>Hỏng</option><option${l.condition==='Sửa chữa'?' selected':''}>Sửa chữa</option></select></td><td><input class="line-note" value="${h(l.note)}"></td><td class="actions"><button type="button" class="del" data-remove-line="${h(l.key)}">Xóa</button></td></tr>`}).join('');updateVoucherWarning()}
function updateVoucherWarning(){syncVoucherDraft();const warn=[];if($('#formVoucherType').value==='OUT'){const stock=buildStock(),sum={};voucherDraft.forEach(l=>{if(l.itemId)sum[l.itemId]=(sum[l.itemId]||0)+n(l.quantity)});Object.entries(sum).forEach(([id,q])=>{const i=itemById(id),available=stock.get(id)?.closing||0;const oldId=$('#editVoucherId').value;if(oldId)linesByVoucher(oldId).filter(t=>t.itemId===id).forEach(t=>available+=n(t.quantityOut)-n(t.quantityIn));if(q>available)warn.push(`${i?.code}: tồn ${fmt(available)}, dự kiến xuất ${fmt(q)}`)})}const el=$('#voucherWarning');el.classList.toggle('hidden',!warn.length);el.innerHTML=warn.length?`Cảnh báo vượt tồn: <strong>${warn.map(h).join('; ')}</strong>`:''}
async function saveVoucher(printWindow=null){
  syncVoucherDraft();
  const lines=voucherDraft.filter(l=>l.itemId&&n(l.quantity)>0).map(l=>({itemId:l.itemId,quantity:n(l.quantity),condition:l.condition,note:l.note}));
  const data={type:$('#formVoucherType').value,date:$('#formVoucherDate').value,number:$('#formVoucherNumber').value,invoiceNo:$('#formInvoiceNo').value,partnerId:$('#formPartner').value,address:$('#formAddress').value,description:$('#formDescription').value,warehouse:$('#formWarehouse').value,delivererReceiver:$('#formDeliverer').value,createdBy:state.me.displayName,storekeeper:$('#formStorekeeper').value,approver:$('#formApprover').value,note:$('#formVoucherNote').value,lines};
  if(!data.description||!data.date||!lines.length){if(printWindow&&!printWindow.closed)printWindow.close();toast('Cần nhập ngày, diễn giải và ít nhất một dòng vật tư',true);return}
  const id=$('#editVoucherId').value;
  try{
    const r=await api('/api/vouchers'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify(data)});
    dirtyVoucher=false;await loadSnapshot(true);toast('Đã lưu phiếu '+r.number);
    if(printWindow)printVoucher(r.id,printWindow);
    showPage('vouchers');
  }catch(e){if(printWindow&&!printWindow.closed)printWindow.close();toast(e.message,true)}
}
function viewVoucher(id){const v=voucherById(id),lines=linesByVoucher(id);openModal(`<h3>${h(typeLabel(v.type))} ${h(v.number)}</h3><div class="info-strip"><span>Ngày: <strong>${viDate(v.date)}</strong></span><span>Đối tác: <strong>${h(v.partnerName||'-')}</strong></span><span>Kho: <strong>${h(v.warehouse||'-')}</strong></span></div><p><strong>Diễn giải:</strong> ${h(v.description)}</p><div class="table-wrap"><table><thead><tr><th>STT</th><th>Ảnh</th><th>Nhóm / Loại</th><th>Mã</th><th>Tên vật tư</th><th>ĐVT</th><th class="num">Số lượng</th><th>Tình trạng</th><th>Ghi chú</th></tr></thead><tbody>${lines.map((t,k)=>{const item=itemById(t.itemId);return `<tr><td>${k+1}</td><td class="image-cell">${imageThumb(item,'voucher-thumb')}</td><td>${h(item?.category||'')}<br><small>${h(item?.itemType||'')}</small></td><td>${h(t.itemCode)}</td><td>${h(t.itemName)}</td><td>${h(t.unit)}</td><td class="num">${fmt(n(t.quantityIn)||n(t.quantityOut))}</td><td>${h(t.condition)}</td><td>${h(t.note)}</td></tr>`}).join('')}</tbody></table></div><div class="form-actions"><button class="btn" data-close-modal>Đóng</button><button class="btn primary" data-modal-print="${h(id)}">In phiếu</button></div>`)}
function companyPrintHeader(){const c=state?.company||{};return `<div class="company-print"><div class="company"><strong>${h(c.name||DEFAULT_COMPANY_NAME)}</strong><div>${h(c.address||'Lô 20-LK19, khu đấu giá QSD Đất Mậu Lương, Kiến Hưng, Hà Nội')}</div><div>MST: ${h(c.taxCode||'0108276927')}</div></div><img src="${PRINT_LOGO_DATA}" alt="KODSDOOR logo"></div>`}
function printVoucher(id,targetWindow=null){const v=voucherById(id),lines=linesByVoucher(id);if(!v)return;const title=v.type==='IN'?'PHIẾU NHẬP KHO':'PHIẾU XUẤT KHO',party=v.type==='IN'?'Người giao hàng':'Người nhận hàng';openPrint(title,`${companyPrintHeader()}<h1>${title}</h1><div class="sub">Ngày ${viDate(v.date)} &nbsp; · &nbsp; Số: <strong>${h(v.number)}</strong></div><div class="meta"><div><b>${party}:</b> ${h(v.delivererReceiver||'')}</div><div><b>Đơn vị:</b> ${h(v.partnerName||'')}</div><div><b>Địa chỉ:</b> ${h(v.address||'')}</div><div><b>Lý do:</b> ${h(v.description||'')}</div><div><b>Nhập/xuất tại kho:</b> ${h(v.warehouse||'')}</div><div><b>Số hóa đơn:</b> ${h(v.invoiceNo||'')}</div></div><table><thead><tr><th>STT</th><th>Nhóm / Loại</th><th>Mã vật tư</th><th>Tên vật tư</th><th>ĐVT</th><th>Số lượng</th><th>Tình trạng</th><th>Ghi chú</th></tr></thead><tbody>${lines.map((t,k)=>`<tr><td>${k+1}</td><td>${h(itemById(t.itemId)?.category||'')}<br><small>${h(itemById(t.itemId)?.itemType||'')}</small></td><td>${h(t.itemCode)}</td><td>${h(t.itemName)}</td><td>${h(t.unit)}</td><td class="num">${fmt(n(t.quantityIn)||n(t.quantityOut))}</td><td>${h(t.condition)}</td><td>${h(t.note)}</td></tr>`).join('')}</tbody></table><div class="note"><b>Ghi chú:</b> ${h(v.note||'')}</div><div class="sign"><div><b>Người lập phiếu</b><span>${h(v.createdBy||'')}</span></div><div><b>${party}</b><span>${h(v.delivererReceiver||'')}</span></div><div><b>Thủ kho</b><span>${h(v.storekeeper||'')}</span></div><div><b>Người duyệt</b><span>${h(v.approver||'')}</span></div></div>`,targetWindow)}

function ledgerData(){const item=itemById($('#ledgerItem').value);if(!item)return{item:null,rows:[]};const from=$('#ledgerFrom').value,to=$('#ledgerTo').value,vmap=new Map(state.vouchers.map(v=>[v.id,v]));let bal=n(item.opening);state.transactions.filter(t=>t.itemId===item.id).forEach(t=>{const v=vmap.get(t.voucherId);if(v&&from&&v.date<from)bal+=n(t.quantityIn)-n(t.quantityOut)});const rows=[{date:'',number:'',desc:'Tồn đầu kỳ',in:'',out:'',bal,note:''}];state.transactions.filter(t=>t.itemId===item.id).map(t=>({t,v:vmap.get(t.voucherId)})).filter(x=>x.v&&(!from||x.v.date>=from)&&(!to||x.v.date<=to)).sort((a,b)=>(a.v.date+a.v.number).localeCompare(b.v.date+b.v.number)).forEach(x=>{bal+=n(x.t.quantityIn)-n(x.t.quantityOut);rows.push({date:x.v.date,number:x.v.number,desc:x.v.description,in:x.t.quantityIn||'',out:x.t.quantityOut||'',bal,note:x.t.note})});return{item,rows}}
function renderLedger(){const {item,rows}=ledgerData();if(!item){$('#ledgerBody').innerHTML='<tr><td colspan="7" class="empty">Chọn vật tư.</td></tr>';return}$('#ledgerInfo').innerHTML=`<span>Mã: <strong>${h(item.code)}</strong></span><span>Tên: <strong>${h(item.name)}</strong></span><span>ĐVT: <strong>${h(item.unit)}</strong></span><span>Tồn hiện tại: <strong>${fmt(buildStock().get(item.id).closing)}</strong></span>`;$('#ledgerBody').innerHTML=rows.map(r=>`<tr><td>${viDate(r.date)}</td><td>${h(r.number)}</td><td>${h(r.desc)}</td><td class="num">${r.in===''?'':fmt(r.in)}</td><td class="num">${r.out===''?'':fmt(r.out)}</td><td class="num ${n(r.bal)<0?'stock-negative':''}">${fmt(r.bal)}</td><td>${h(r.note)}</td></tr>`).join('')}
function reportData(){
  const from=$('#reportFrom').value,to=$('#reportTo').value,group=$('#reportCategory').value,itemType=$('#reportItemType').value,partner=$('#reportPartner')?.value||'',vmap=new Map(state.vouchers.map(v=>[v.id,v]));
  return state.items.filter(i=>(!group||i.category===group)&&(!itemType||i.itemType===itemType)).map(i=>{
    let opening=partner?0:n(i.opening),qin=0,qout=0;
    state.transactions.filter(t=>t.itemId===i.id).forEach(t=>{const v=vmap.get(t.voucherId);if(!v||partner&&v.partnerId!==partner)return;const delta=n(t.quantityIn)-n(t.quantityOut);if(from&&v.date<from)opening+=delta;else if((!from||v.date>=from)&&(!to||v.date<=to)){qin+=n(t.quantityIn);qout+=n(t.quantityOut)}});
    return{...i,reportOpening:opening,reportIn:qin,reportOut:qout,reportClosing:opening+qin-qout}
  }).filter(i=>!partner||i.reportOpening!==0||i.reportIn!==0||i.reportOut!==0).sort((a,b)=>a.category.localeCompare(b.category,'vi')||(a.itemType||'').localeCompare(b.itemType||'','vi')||a.code.localeCompare(b.code,'vi')||a.name.localeCompare(b.name,'vi'))
}
function renderReport(){
  reportRows=reportData();const ti=reportRows.reduce((sum,x)=>sum+x.reportIn,0),to=reportRows.reduce((sum,x)=>sum+x.reportOut,0),neg=reportRows.filter(x=>x.reportClosing<0).length,partnerId=$('#reportPartner')?.value||'',partner=partnerById(partnerId);const oh=$('#reportOpeningHeader'),ch=$('#reportClosingHeader');if(oh)oh.textContent=partner?'Đầu kỳ CT':'Tồn đầu kỳ';if(ch)ch.textContent=partner?'Số dư CT':'Tồn cuối kỳ';
  $('#reportTotals').innerHTML=`${partner?`<span>Công trình/Đối tác: <strong>${h(partner.name)}</strong></span>`:''}<span>Số mã: <strong>${fmt(reportRows.length)}</strong></span><span>Tổng nhập: <strong>${fmt(ti)}</strong></span><span>Tổng xuất: <strong>${fmt(to)}</strong></span><span>${partner?'Chênh lệch âm':'Tồn âm'}: <strong>${fmt(neg)}</strong></span>${partner?'<span class="muted">Số dư công trình = nhập − xuất, không phải tồn kho tổng.</span>':''}`;
  $('#reportBody').innerHTML=reportRows.length?reportRows.map((i,k)=>`<tr><td>${k+1}</td><td>${h(i.category)}</td><td>${h(i.itemType||'')}</td><td>${h(i.code)}</td><td>${h(i.name)}</td><td>${h(i.unit)}</td><td class="num">${fmt(i.reportOpening)}</td><td class="num">${fmt(i.reportIn)}</td><td class="num">${fmt(i.reportOut)}</td><td class="num ${i.reportClosing<0?'stock-negative':''}">${fmt(i.reportClosing)}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">Không có phát sinh phù hợp.</td></tr>'
}
function renderUsers(){if(!isAdmin())return;$('#usersBody').innerHTML=(state.users||[]).map(u=>`<tr><td><strong>${h(u.username)}</strong></td><td>${h(u.displayName)}</td><td><span class="badge ${u.role}">${roleLabel(u.role)}</span></td><td>${u.active?'Đang hoạt động':'Đã khóa'}</td><td>${new Date(u.updatedAt).toLocaleString('vi-VN')}</td><td class="actions"><button data-edit-user="${h(u.id)}">Sửa</button>${u.id!==state.me.id?`<button class="del" data-delete-user="${h(u.id)}">Xóa</button>`:''}</td></tr>`).join('')}
function userModal(id=''){const u=id?state.users.find(x=>x.id===id):{username:'',displayName:'',role:'viewer',active:true};openModal(`<h3>${id?'Sửa':'Thêm'} người dùng</h3><form id="userModalForm"><label>Tên đăng nhập<input name="username" value="${h(u.username)}" required></label><label>Họ tên<input name="displayName" value="${h(u.displayName)}" required></label><label>Quyền<select name="role"><option value="admin"${u.role==='admin'?' selected':''}>Quản trị</option><option value="keeper"${u.role==='keeper'?' selected':''}>Thủ kho</option><option value="viewer"${u.role==='viewer'?' selected':''}>Chỉ xem</option></select></label><label>Mật khẩu ${id?'(để trống nếu không đổi)':''}<input name="password" type="password" ${id?'':'required'}></label><label class="check"><input name="active" type="checkbox"${u.active?' checked':''}> Tài khoản hoạt động</label><div class="form-actions"><button type="button" class="btn" data-close-modal>Hủy</button><button class="btn primary">Lưu</button></div></form>`);$('#userModalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d=Object.fromEntries(f);d.active=f.has('active');try{await api('/api/users'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify(d)});closeModal();await loadSnapshot(true);renderUsers();toast('Đã lưu người dùng')}catch(err){toast(err.message,true)}}}
async function loadAudit(){try{const r=await api('/api/audit?limit=200');$('#auditPanel').classList.remove('hidden');$('#auditBody').innerHTML=r.data.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('vi-VN')}</td><td>${h(x.username)}</td><td>${h(x.action)}</td><td>${h(x.entity_type)} ${h(x.entity_id)}</td><td>${h(x.details)}</td></tr>`).join('')}catch(e){toast(e.message,true)}}
function renderSettings(){if(!isAdmin())return;$('#settingCompanyName').value=state.company?.name||'';$('#settingCompanyAddress').value=state.company?.address||'';$('#settingTaxCode').value=state.company?.taxCode||'';$('#settingWarehouse').value=state.settings?.defaultWarehouse||'Kho công ty';$('#settingAllowNegative').checked=!!state.settings?.allowNegative}

function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden');$('#modalContent').innerHTML=''}
function passwordModal(){openModal(`<h3>Đổi mật khẩu</h3><form id="passwordForm"><label>Mật khẩu hiện tại<input name="currentPassword" type="password" required></label><label>Mật khẩu mới<input name="newPassword" type="password" minlength="6" required></label><label>Nhập lại mật khẩu mới<input name="confirm" type="password" minlength="6" required></label><div class="form-actions"><button type="button" class="btn" data-close-modal>Hủy</button><button class="btn primary">Đổi mật khẩu</button></div></form>`);$('#passwordForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.newPassword!==d.confirm){toast('Mật khẩu nhập lại không khớp',true);return}try{await api('/api/change-password',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Đã đổi mật khẩu')}catch(err){toast(err.message,true)}}}
function createPrintWindow(){
  const w=window.open('','_blank');
  if(!w){toast('Trình duyệt đang chặn cửa sổ in. Hãy cho phép Pop-up cho địa chỉ phần mềm.',true);return null}
  w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Đang chuẩn bị phiếu...</title></head><body style="font-family:Arial;padding:30px">Đang chuẩn bị phiếu...</body></html>');w.document.close();return w
}
function openPrint(title,content,targetWindow=null){
  const w=targetWindow&&!targetWindow.closed?targetWindow:createPrintWindow();if(!w)return;
  const printCss=`@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{font:12.5px Arial,sans-serif;color:#111;margin:0;padding:82px 10px 18px}.print-tools{position:fixed;left:0;right:0;top:0;min-height:62px;z-index:1000;display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:8px;background:#f4f5f7;border-bottom:1px solid #d4d8dd;box-shadow:0 2px 8px rgba(0,0,0,.12);padding:8px}.print-tools button{border:1px solid #b8bdc4;background:#fff;padding:8px 14px;border-radius:7px;cursor:pointer;font-weight:700}.print-tools button:hover{background:#eef1f4}.print-tools .print-main{background:#c61d34;border-color:#c61d34;color:#fff}.print-tools .print-main:hover{background:#a5162a}.print-tools .resize-active{background:#253858;border-color:#253858;color:#fff}.resize-help{width:100%;text-align:center;font-size:11px;color:#59636e;line-height:1.25}.print-content{max-width:100%;overflow-x:auto;padding:0 2px}.company{font-size:11px;line-height:1.45}.company strong{font-size:14px}.company-print{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:2px solid #cfd5db;padding-bottom:8px;margin-bottom:10px}.company-print img{width:205px;max-width:40%;height:auto;object-fit:contain}h1{text-align:center;font-size:21px;margin:12px 0 3px;color:#c61d34}.sub{text-align:center;margin-bottom:12px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:5px 16px;margin-bottom:11px}.meta div:nth-child(4),.meta div:nth-child(5){grid-column:span 2}table{width:100%;border-collapse:collapse;table-layout:auto}thead{display:table-header-group}tfoot{display:table-footer-group}th,td{border:1px solid #222;padding:5px;vertical-align:top;overflow-wrap:anywhere}th{text-align:center;background:#f3f3f3}tr{break-inside:avoid;page-break-inside:avoid}.num{text-align:right;white-space:nowrap}.note{margin-top:10px}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;text-align:center;margin-top:20px;break-inside:avoid;page-break-inside:avoid}.sign div{min-height:82px}.sign b{display:block}.sign span{display:block;margin-top:52px;font-weight:bold}.resize-mode table{table-layout:fixed}.resize-mode th,.resize-mode td{position:relative}.col-resizer{display:none;position:absolute;right:-4px;top:0;width:8px;height:100%;cursor:col-resize;z-index:30;user-select:none}.col-resizer:after{content:'';position:absolute;left:3px;top:0;bottom:0;border-left:2px solid rgba(198,29,52,.58)}.row-resizer{display:none;position:absolute;left:0;right:0;bottom:-4px;height:8px;cursor:row-resize;z-index:25;user-select:none}.row-resizer:after{content:'';position:absolute;left:0;right:0;top:3px;border-top:2px solid rgba(37,56,88,.52)}.resize-mode .col-resizer,.resize-mode .row-resizer{display:block}.resize-mode th:hover,.resize-mode td:hover{background-image:linear-gradient(rgba(37,56,88,.035),rgba(37,56,88,.035))}.resizing,.resizing *{cursor:col-resize!important;user-select:none!important}.resizing-row,.resizing-row *{cursor:row-resize!important;user-select:none!important}@media print{body{padding:0}.print-tools{display:none}.print-content{overflow:visible;padding:0}.col-resizer,.row-resizer{display:none!important}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}`;
  const printJs=`(function(){
    const d=document,content=d.getElementById('printContent'),toggle=d.getElementById('resizeToggle'),autoBtn=d.getElementById('autoFitBtn'),resetBtn=d.getElementById('resetSizeBtn');
    const originals=[...content.querySelectorAll('table')].map(t=>t.outerHTML);
    let resizeOn=false;
    function px(v){return Math.max(0,Number(v)||0)}
    function tableRows(table){return [...table.querySelectorAll('tr')]}
    function firstHeaderRow(table){return table.querySelector('thead tr:last-child')||table.querySelector('tr')}
    function ensureColumns(table){
      let colgroup=table.querySelector(':scope > colgroup');
      const row=firstHeaderRow(table);if(!row)return null;
      let count=0;[...row.children].forEach(c=>count+=Math.max(1,Number(c.colSpan)||1));
      if(!colgroup){colgroup=d.createElement('colgroup');for(let i=0;i<count;i++)colgroup.appendChild(d.createElement('col'));table.insertBefore(colgroup,table.firstChild)}
      const cols=[...colgroup.children];
      while(cols.length<count){const c=d.createElement('col');colgroup.appendChild(c);cols.push(c)}
      if(!cols.some(c=>c.style.width)){
        const tableWidth=Math.max(300,table.getBoundingClientRect().width),base=tableWidth/count;
        cols.slice(0,count).forEach(c=>c.style.width=base+'px');
      }
      return cols.slice(0,count)
    }
    function clearHandles(table){table.querySelectorAll('.col-resizer,.row-resizer').forEach(x=>x.remove())}
    function addHandles(table){
      clearHandles(table);const cols=ensureColumns(table);if(!cols)return;
      const row=firstHeaderRow(table),cells=[...row.children];let logical=0;
      cells.forEach((cell,cellIndex)=>{
        const span=Math.max(1,Number(cell.colSpan)||1);logical+=span;
        if(logical<cols.length){
          const handle=d.createElement('span');handle.className='col-resizer';handle.title='Kéo để thay đổi độ rộng cột. Nhấp đúp để tự căn cột.';cell.appendChild(handle);
          handle.addEventListener('mousedown',ev=>{
            ev.preventDefault();ev.stopPropagation();
            const leftIndex=logical-1,rightIndex=logical;
            const leftCol=cols[leftIndex],rightCol=cols[rightIndex];
            const leftStart=px(getComputedStyle(leftCol).width)||px(leftCol.style.width)||60;
            const rightStart=px(getComputedStyle(rightCol).width)||px(rightCol.style.width)||60;
            const startX=ev.clientX,min=32;d.body.classList.add('resizing');
            function move(e){const delta=e.clientX-startX,newLeft=Math.max(min,leftStart+delta),used=newLeft-leftStart,newRight=Math.max(min,rightStart-used),actual=rightStart-newRight;leftCol.style.width=Math.max(min,leftStart+actual)+'px';rightCol.style.width=newRight+'px'}
            function up(){d.removeEventListener('mousemove',move);d.removeEventListener('mouseup',up);d.body.classList.remove('resizing')}
            d.addEventListener('mousemove',move);d.addEventListener('mouseup',up)
          });
          handle.addEventListener('dblclick',ev=>{ev.preventDefault();ev.stopPropagation();autoFitColumn(table,logical-1)})
        }
      });
      tableRows(table).forEach(tr=>{
        const cell=tr.cells[0];if(!cell)return;const handle=d.createElement('span');handle.className='row-resizer';handle.title='Kéo để thay đổi chiều cao hàng. Nhấp đúp để tự căn hàng.';cell.appendChild(handle);
        handle.addEventListener('mousedown',ev=>{
          ev.preventDefault();ev.stopPropagation();const startY=ev.clientY,startH=Math.max(20,tr.getBoundingClientRect().height);d.body.classList.add('resizing-row');
          function move(e){tr.style.height=Math.max(20,startH+(e.clientY-startY))+'px'}
          function up(){d.removeEventListener('mousemove',move);d.removeEventListener('mouseup',up);d.body.classList.remove('resizing-row')}
          d.addEventListener('mousemove',move);d.addEventListener('mouseup',up)
        });
        handle.addEventListener('dblclick',ev=>{ev.preventDefault();ev.stopPropagation();tr.style.height='auto'})
      })
    }
    function autoFitColumn(table,index){
      const cols=ensureColumns(table);if(!cols||!cols[index])return;
      const old=table.style.tableLayout;table.style.tableLayout='auto';cols[index].style.width='auto';
      requestAnimationFrame(()=>{const cells=[];table.querySelectorAll('tr').forEach(tr=>{let pos=0;[...tr.cells].forEach(c=>{const span=Math.max(1,Number(c.colSpan)||1);if(index>=pos&&index<pos+span&&span===1)cells.push(c);pos+=span})});const width=Math.min(380,Math.max(38,...cells.map(c=>c.scrollWidth+14)));cols[index].style.width=width+'px';table.style.tableLayout=old||'fixed'})
    }
    function autoFitAll(){
      content.querySelectorAll('table').forEach(table=>{
        clearHandles(table);table.style.tableLayout='auto';table.querySelectorAll(':scope > colgroup').forEach(x=>x.remove());tableRows(table).forEach(tr=>tr.style.height='auto');
        requestAnimationFrame(()=>{ensureColumns(table);table.style.tableLayout='fixed';addHandles(table)})
      })
    }
    function resetAll(){
      const tables=[...content.querySelectorAll('table')];tables.forEach((t,i)=>{const box=d.createElement('div');box.innerHTML=originals[i]||t.outerHTML;t.replaceWith(box.firstElementChild)});
      requestAnimationFrame(()=>content.querySelectorAll('table').forEach(addHandles))
    }
    function toggleResize(){resizeOn=!resizeOn;d.body.classList.toggle('resize-mode',resizeOn);toggle.classList.toggle('resize-active',resizeOn);toggle.textContent=resizeOn?'XONG CHỈNH KÍCH THƯỚC':'CHỈNH CỘT / HÀNG'}
    content.querySelectorAll('table').forEach(addHandles);
    toggle.addEventListener('click',toggleResize);autoBtn.addEventListener('click',autoFitAll);resetBtn.addEventListener('click',resetAll);
  })();`;
  w.document.open();w.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${h(title)}</title><style>${printCss}</style></head><body><div class="print-tools"><button id="resizeToggle" type="button">CHỈNH CỘT / HÀNG</button><button id="autoFitBtn" type="button">TỰ CĂN</button><button id="resetSizeBtn" type="button">KHÔI PHỤC</button><button class="print-main" type="button" onclick="window.print()">IN BÁO CÁO</button><button type="button" onclick="window.close()">ĐÓNG</button><div class="resize-help">Bật Chỉnh cột/hàng → kéo mép phải tiêu đề để đổi độ rộng cột; kéo mép dưới dòng để đổi chiều cao. Nhấp đúp mép để tự căn.</div></div><div id="printContent" class="print-content">${content}</div><script>${printJs}<\/script></body></html>`);w.document.close();w.focus()
}

function printTable(title,subtitle,headers,rows,targetWindow=null){openPrint(title,`${companyPrintHeader()}<h1>${h(title)}</h1><div class="sub">${h(subtitle)}</div><table><thead><tr>${headers.map(x=>`<th>${h(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,k)=>`<td${k>=3?' class="num"':''}>${h(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`,targetWindow)}

function exportInventory(){const stock=buildStock(),rows=[['STT','Nhóm vật tư','Loại vật tư','Mã hàng','Tên hàng','ĐVT','Tồn đầu','Nhập','Xuất','Tồn hiện tại','Tồn tối thiểu']];filteredItems().forEach((i,k)=>{const st=stock.get(i.id);rows.push([k+1,i.category,i.itemType,i.code,i.name,i.unit,st.opening,st.in,st.out,st.closing,i.minStock])});download('Ton_kho_'+today()+'.csv',csv(rows),'text/csv;charset=utf-8')}
function exportPartners(){download('Doi_tac_'+today()+'.csv',csv([['Mã','Tên','Địa chỉ','MST','Ghi chú'],...state.partners.map(p=>[p.code,p.name,p.address,p.taxCode,p.note])]),'text/csv;charset=utf-8')}
function exportVouchers(){const rows=[['Ngày','Số phiếu','Loại','Đối tác','Diễn giải','Mã vật tư','Tên vật tư','ĐVT','Nhập','Xuất','Tình trạng','Ghi chú']];filteredVouchers().forEach(v=>linesByVoucher(v.id).forEach(t=>rows.push([v.date,v.number,typeLabel(v.type),v.partnerName,v.description,t.itemCode,t.itemName,t.unit,t.quantityIn,t.quantityOut,t.condition,t.note])));download('Phieu_nhap_xuat_'+today()+'.csv',csv(rows),'text/csv;charset=utf-8')}
function exportLedger(){const {item,rows}=ledgerData();if(!item)return;download('So_kho_'+item.code+'_'+today()+'.csv',csv([['Ngày','Số phiếu','Diễn giải','Nhập','Xuất','Tồn','Ghi chú'],...rows.map(r=>[r.date,r.number,r.desc,r.in,r.out,r.bal,r.note])]),'text/csv;charset=utf-8')}
function exportReport(){renderReport();const partner=partnerById($('#reportPartner')?.value||''),name=partner?'Bao_cao_cong_trinh_'+partner.code:'Bao_cao_NXT';download(name+'_'+today()+'.csv',csv([['STT','Nhóm vật tư','Loại vật tư','Mã hàng','Tên hàng','ĐVT',partner?'Đầu kỳ công trình':'Tồn đầu','Nhập','Xuất',partner?'Số dư công trình':'Tồn cuối'],...reportRows.map((i,k)=>[k+1,i.category,i.itemType,i.code,i.name,i.unit,i.reportOpening,i.reportIn,i.reportOut,i.reportClosing])]),'text/csv;charset=utf-8')}
